<script setup lang="ts">import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import{listFeedbacks}from'@/api/feedbacks';import{useResponsive}from'@/composables/useResponsive';import StatusTag from'@/components/StatusTag.vue';const router=useRouter();const{isMobile}=useResponsive();const rows=ref<any[]>([]);onMounted(async()=>rows.value=(await listFeedbacks()).items)</script>
<template><div class="page"><div class="head"><div class="page-title">反馈中心</div><el-button type="primary" @click="router.push('/feedbacks/new')">提交反馈</el-button></div><el-table v-if="!isMobile" :data="rows"><el-table-column prop="feedback_no" label="编号"/><el-table-column prop="title" label="标题" min-width="240"/><el-table-column prop="feedback_type" label="类型"/><el-table-column label="状态"><template #default="s"><StatusTag :status="s.row.status"/></template></el-table-column><el-table-column label="操作"><template #default="s"><el-link type="primary" @click="router.push('/feedbacks/'+s.row.id)">查看</el-link></template></el-table-column></el-table><div v-else class="cards"><el-card v-for="r in rows" :key="r.id" @click="router.push('/feedbacks/'+r.id)"><b>{{r.feedback_no}} {{r.title}}</b><div class="meta"><span>{{r.feedback_type}}</span><StatusTag :status="r.status"/></div></el-card></div></div></template>
<style scoped>.head{display:flex;justify-content:space-between}.cards{display:grid;gap:10px}.meta{display:flex;justify-content:space-between;margin-top:10px;color:#64748b}</style>
